"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7540],{16355:e=>{e.exports=JSON.parse('{"functions":[{"name":"show","desc":"Start showing the arc for an equipped throwable. Idempotent: a second call\\ntears the previous session down first. Captures `character`/`tool` for the\\nper-frame origin + raycast filtering.","params":[{"name":"config","desc":"","lua_type":"WeaponTypes.ThrowableWeaponConfig"},{"name":"character","desc":"","lua_type":"Model"},{"name":"tool","desc":"","lua_type":"Tool"}],"returns":[],"function_type":"static","source":{"line":175,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}},{"name":"hide","desc":"Stop showing the arc and destroy the whole pool. Safe to call when nothing\\nis showing.","params":[],"returns":[],"function_type":"static","source":{"line":218,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}}],"properties":[],"types":[],"name":"TrajectoryPreview","desc":"Client-only predictive arc for thrown weapons (Grenade, Dynamite). While a throwable\\nis equipped, `show` starts a RenderStepped loop that recomputes the ballistic\\nparabola each frame from the live camera + handle, raycasts each segment to stop\\nat real geometry, and positions a fixed pool of reused green neon parts plus a\\nlanding marker. The arc starts at the SAME offset point the server spawns the\\nreal clone (SPAWN_OFFSET) and uses the SAME upward aim bias as ThrowableHandler,\\nso the preview matches the projectile\'s actual free-flight path. Purely cosmetic\\nand local \u2014 no networking. `hide` tears the whole pool down via one Janitor.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/TrajectoryPreview.luau"}}')}}]);